-- The 34 ward symbol rows of Palladium Fantasy printed 126-133
-- 34 spells rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~165-ward-symbols.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.
-- Close-out package C3, the catalog half: the Diabolist's ward symbols as
-- spells rows in the `ward` tradition (BOOK-INGEST-AUDIT F123; Nate's ruling 9
-- of 2026-10-04: a symbol catalog shown on the sheet, no builder).
--
-- Thirty-four rows cover the 52 symbols of the plate on printed 127: 4 alarms,
-- 22 conditions and 6 major wards one row each, and the seven colors and the
-- thirteen numerals one row per group, as the book gives each group one entry.
-- Every name carries a kind prefix, because the codex splits a tradition into
-- families by it. Alarm, Condition and Major Ward are the plate's own groups;
-- Descriptive is this catalog's label for Colors and Numbers.
--
-- No symbol prints a cost of its own. Every ppe is the general rule of printed
-- 120 and 122: one P.P.E. a symbol, five for power, twenty for permanence.
-- There is no column for components or power words, so each row's description
-- carries them.
--
-- Where the book contradicts itself the row states both sides with their
-- pages: the trigger alarm's range (60 feet on printed 126, 10 feet per level
-- on 133), the power ward's components (printed 124, twice), and whether
-- inflict may be joined to area affect (allowed on printed 123 and 126,
-- forbidden on 126 and 132).
--
-- Read off renders of printed 120-133 by one agent and checked row by row
-- against renders by book-reconcile: no wrong figure, page, cost or power
-- word; seven wording corrections applied before this was generated.
-- ~166 gives the Diabolist these rows.

INSERT OR IGNORE INTO spells (name, level, ppe, ppe_note, variant_note, source, source_book, system, range, duration, damage, saving_throw, area_of_effect, casting_time, description, same_spell_as, tradition, ppe_permanent) VALUES
  ('Alarm: Magic', 0, 1, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.126', 'palladium-fantasy', 'Magic used on the warded item or within 10 feet (3 m) of it', NULL, NULL, NULL, NULL, NULL, 'Answers to magic. It goes off when the warded item is touched by a practitioner of magic, a spell casting priest, a creature of magic or a supernatural being, or when magic is used on it or within 10 feet (3 m), and sends a silent alarm to its maker wherever the maker is. Does no damage; may stand alone as a one-symbol ward. Components: any substance - drawn in dirt or dust, chalk, charcoal, paint or blood, or carved or etched in any material. One melee round to draw or paint, two to three hours carved. Power words (all alarms): Acba yin Kym-nark-mar.', NULL, 'ward', NULL),
  ('Alarm: Silent', 0, 1, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.126', 'palladium-fantasy', NULL, NULL, NULL, NULL, NULL, NULL, 'Goes off when the warded item (or area, with an area affect symbol) is disturbed. Only the maker hears it, in the head, the instant it happens, and knows which alarm it is - at any distance, even from another dimension. Does no damage; may stand alone as a one-symbol ward. Components: any substance - drawn in dirt or dust, chalk, charcoal, paint or blood, or carved or etched in any material. One melee round to draw or paint, two to three hours carved. Power words (all alarms): Acba yin Kym-nark-mar.', NULL, 'ward', NULL),
  ('Alarm: Sound', 0, 1, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.126', 'palladium-fantasy', 'Heard within a 100 foot (30.5 m) radius per level of the Diabolist', 'Two minutes per level of the Diabolist', NULL, NULL, NULL, NULL, 'A loud siren-like noise set off by any disturbance of the warded item, even a gentle touch. It carries 100 feet (30.5 m) per level of the maker and blares two minutes per level. With an area affect symbol it sounds when someone enters the area. Does no damage; may stand alone as a one-symbol ward. Components: any substance - drawn in dirt or dust, chalk, charcoal, paint or blood, or carved or etched in any material. One melee round to draw or paint, two to three hours carved. Power words (all alarms): Acba yin Kym-nark-mar.', NULL, 'ward', NULL),
  ('Alarm: Trigger', 0, 1, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.126', 'palladium-fantasy', '60 foot (18.3 m) radius (printed 126); printed 133 says 10 feet (3 m) per level of the Diabolist', NULL, NULL, NULL, NULL, NULL, 'Sends a silent alarm to the maker AND sets off one other ward, ward phrase or numbered sequence, which lies dormant until then even if touched. Printed 126 puts the linked ward within a 60 foot (18.3 m) radius; the special entry on printed 133 says 10 feet (3 m) per level - the book prints both. One trigger links to one ward, phrase or sequence, never to everything in reach. It can also open a phrase that names the condition under which it fires (when dark, when touched by evil or undead, a true name). Components: any substance - drawn in dirt or dust, chalk, charcoal, paint or blood, or carved or etched in any material. One melee round to draw or paint, two to three hours carved. Power words (all alarms): Acba yin Kym-nark-mar.', NULL, 'ward', NULL),
  ('Major Ward: Area Affect', 0, 1, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.126', 'palladium-fantasy', '10 foot (3 m) radius, +5 feet (1.5 m) per level of the Diabolist', NULL, NULL, 'Each character in the radius saves vs ward magic (base 14; typical range 14-16)', 'Radius set by the maker from 5 feet (1.5 m) up to the current maximum', NULL, 'Makes the phrase cover an area, not one object: a 10 foot (3 m) radius plus 5 feet (1.5 m) per level of the maker, which the maker may shrink to as little as 5 feet. It must stand with a condition, protection from, protection by infliction or inflict symbol (printed 132 bars it beside inflict). The area is fixed on the spot where the ward went off and does not move; everyone inside, or entering later, saves or is affected, the maker excepted. Only on immobile objects - never on a living being, cloth or fabric. Components: drawn in the Diabolist''s own blood. One melee round to draw or paint, two hours carved. Power word: Agu.', NULL, 'ward', NULL),
  ('Major Ward: Inflict', 0, 1, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.132', 'palladium-fantasy', NULL, NULL, NULL, NULL, NULL, NULL, 'Puts a condition on a living being: the person it is inscribed on suffers the condition symbol that must accompany it (a two-symbol phrase), set off by the maker. Used to torture, to instil an ability or to lay on a harmless condition. The book prints area affect both ways: printed 123 (twice) and the first column of printed 126 join inflict to area affect, while the Conditions note on printed 126 and this entry on printed 132 forbid it and give that work to protection by infliction. Components: sawdust or wood in a binding agent, or carved from one piece of any wood; to torture, drawn in the Diabolist''s own blood, usually on the forehead. One melee round to draw or paint, two hours carved. Power word: Lo-kum.', NULL, 'ward', NULL),
  ('Major Ward: Permanence', 0, 20, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.132', 'palladium-fantasy', NULL, 'Permanent', 'None in itself; removing one from a living being does 1D6x10 direct to its hit points and 2D4x10 to everyone within 5 feet (1.5 m)', NULL, NULL, NULL, 'Fixes the ward to its item or place, makes the whole phrase indestructible and makes the other magic there - a ward, circle, curse or spell - permanent and always active. Must be combined with an area affect symbol. Only a mystic energy drain ward or a power leech circle can halve it for a time. It cannot be deactivated.On a living creature it must be sewn on, bonds after a year, cannot go on creatures of magic or supernatural beings, and cannot bestow attack spells. Used to inflict, with protection by infliction, protection from and area affect. Components: carved from the bone of a dragon, demon, deevil, godling or god, all parts from the same bone and the body in one flawless piece; 120 hours to carve. Power words: Xy-Lictalon yin Ariel-Rapere-kyn yin Agu yin Netosa.', NULL, 'ward', NULL),
  ('Major Ward: Power', 0, 5, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.132-133', 'palladium-fantasy', NULL, 'Double the normal duration of the ward it accompanies', 'Doubles the effect, damage, range and duration of the ward or ward phrase', NULL, NULL, NULL, 'Doubles the damage, the range or radius and the duration of the other wards it is combined with. Used with inflict, protection by infliction, area affect and protection from. Costs 5 P.P.E. to energize and 10 to deactivate. Components: printed 124 names the ground bone of a Hydra''s tooth or a Unicorn horn, drawn or painted; the creation-time list on the same page says ground bone, humanoid or animal. Four melee rounds (60 seconds) to draw or paint, 18 hours carved. Power words: Xy yin Agu yin Ya-ahk-met.', NULL, 'ward', NULL),
  ('Major Ward: Protection From', 0, 1, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.133', 'palladium-fantasy', NULL, '10 minutes per level of the Diabolist, unless the condition states otherwise', NULL, NULL, NULL, NULL, 'Repels, holds at bay or gives a bonus to save against the one condition symbol that must accompany it (a two-symbol phrase); each condition row states its own protection. Worn on a person it is placed on the flesh and must be visible - forehead or chest. One thing per phrase; bonuses do not add up, and only one protection ward may be active on a person at a time. An area affect symbol protects the whole radius, but never on a person. Components: beeswax, melted and applied, moulded warm or carved from a block; colouring does no harm. One melee round to draw or paint, four hours carved. The entry prints no power word.', NULL, 'ward', NULL),
  ('Major Ward: Protection by Infliction', 0, 1, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.133', 'palladium-fantasy', NULL, NULL, NULL, NULL, NULL, NULL, 'Placed on an object and set off only when it is disturbed: it protects by inflicting the condition symbol that must accompany it on whoever touches the object (a two-symbol phrase). With an area affect symbol the condition falls on everyone in the radius who fails to save, a three-symbol phrase. An alarm or the power symbol may be added. One inflicting condition per phrase; a second condition may only describe (evil, good and magic usually). Components: sawdust or wood in a binding agent, or carved from one piece of any wood, or cut into wood. One melee round to draw or paint, four hours carved. The entry prints no power word.', NULL, 'ward', NULL),
  ('Condition: Agony', 0, 1, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.128', 'palladium-fantasy', NULL, 'Two melee rounds per level of the Diabolist', '2D4 per level of the Diabolist', NULL, NULL, NULL, 'Stabbing pain in head, neck and stomach with no mark left. The victim loses initiative, all combat bonuses and all but one attack per melee round (none if bound); speed and skill performance are halved. Used with inflict, protection by infliction and area affect. Protection from agony (printed 133): penalties from physical pain or pain-inducing magic or psionics are halved, as is that magic''s duration. Components: quicksilver (mercury in a resin or glue binder, at least 64% mercury). Drawn in two melee rounds; carved and glued in three hours. Power words: Pein yin Netosa.', NULL, 'ward', NULL),
  ('Condition: Blind', 0, 1, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.128', 'palladium-fantasy', NULL, '10 minutes per level of the Diabolist', 'None; temporary loss of sight', NULL, NULL, NULL, 'Temporary blindness: -9 to strike, parry and dodge, no initiative, and speed must drop by 80% to move without stumbling and falling. Used with inflict, protection by infliction and area affect. Protection from blind (printed 133): +3 to save vs magic and psionic blindness. Components: quicksilver (mercury in a resin or glue binder, at least 64% mercury). Drawn in two melee rounds; carved and glued in three hours. Power words: Acba yin Keron.', NULL, 'ward', NULL),
  ('Condition: Burning Pain', 0, 1, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.128', 'palladium-fantasy', NULL, 'Four melee rounds per level of the Diabolist', '1D6 per level of the Diabolist', NULL, NULL, NULL, 'Pain as if every muscle were on fire, leaving no scars or burns. The victim loses initiative and all combat bonuses, attacks per melee round are halved (none if bound), and speed and skill performance fall by 80%. Used with inflict, protection by infliction and area affect. Protection from burning pain is printed as not applicable. Components: quicksilver (mercury in a resin or glue binder, at least 64% mercury). Drawn in two melee rounds; carved and glued in three hours. Power words: Acba yin Tarm-kin-toe yin Seraph-mytyn.', NULL, 'ward', NULL),
  ('Condition: Charm', 0, 1, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.128', 'palladium-fantasy', NULL, 'Four minutes per level of the Diabolist', 'None', NULL, NULL, NULL, 'The victim takes the ward''s maker for a friend and obeys any command that is not life threatening or strongly against alignment. With the maker absent the victim is listless: -4 on initiative, -2 on all combat bonuses, -1 attack per melee and -10% on skills. Used with inflict, protection by infliction, area affect and protection from. Protection from charm (printed 133): +3 to save vs all magical and psionic charms, including charismatic aura, love charm, domination, trance and the gaze of vampires, succubi and incubi. Components: gold (dust in a glue or paste, poured, cast or etched; at least 64% gold). Drawn in two melee rounds; carved and glued in three hours. Power words: Acba yin Lo-kum.', NULL, 'ward', NULL),
  ('Condition: Cold', 0, 1, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.128', 'palladium-fantasy', NULL, 'One minute (4 melee rounds) per level of the Diabolist', 'One point per melee round', NULL, NULL, NULL, 'A bone-chilling cold that hurts and distracts: -2 on initiative, -1 to strike and -5% on skills. Used with inflict, protection by infliction, area affect and protection from. Protection from cold (printed 133): cold is endured twice as long without ill effect, and its penalties and damage are halved. With mystic energy drain it takes the chill from the air and warms the area. Components: silver (dust in a glue or paste, poured, cast or etched; at least 64% silver). Drawn in two melee rounds; carved and glued in three hours. Power words: Cherubot-kyn.', NULL, 'ward', NULL),
  ('Condition: Confusion', 0, 1, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.128', 'palladium-fantasy', NULL, 'Two minutes (8 melee rounds) per level of the Diabolist', 'None', NULL, NULL, NULL, 'Confused and disoriented: -5 on initiative, -2 to strike, parry and dodge, -10% on skills and no sense of direction or time. Used with inflict, protection by infliction and area affect. Protection from confusion (printed 133): +2 to save vs wisps of confusion and other disorienting magic. With mystic energy drain it clears confusion caused by magic, psionics, drugs or disease for the ward''s duration. Components: quicksilver (mercury in a resin or glue binder, at least 64% mercury). Drawn in two melee rounds; carved and glued in three hours. Power words: Lictalon yin Tarm-kin-toe.', NULL, 'ward', NULL),
  ('Condition: Dark', 0, 1, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.128', 'palladium-fantasy', NULL, 'Two minutes per level of the Diabolist', 'None; normal vision is blind', NULL, '10 foot (3 m) radius per level of the Diabolist', NULL, 'Unnatural darkness. Those with ordinary sight are blind in it (-9 to strike, parry and dodge) and nightvision loses half its range and clarity. Used with inflict (darkness around one person), protection by infliction, area affect and protection from. Protection from dark: nightvision of 60 feet (18.3 m) even in magic darkness. With mystic energy drain a dark area turns dimly lit, as by twilight or one torch. Components: silver (dust in a glue or paste, poured, cast or etched; at least 64% silver). Drawn in two melee rounds; carved and glued in three hours. Power words: Acba yin Pein.', NULL, 'ward', NULL),
  ('Condition: Death', 0, 1, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.128', 'palladium-fantasy', NULL, 'One melee round per level of the Diabolist', '1D6 per level of the Diabolist direct to hit points, per melee round', NULL, NULL, NULL, 'Damage straight to hit points; at zero or just below the victim falls into a coma whatever S.D.C. remains, and is -20% to save vs coma/death. Used with inflict, protection by infliction, area affect and protection from. Protection from death (printed 133): +2 to save vs the death ward, spell and circle and +20% to save vs coma; add the evil symbol and animated dead, skeletons, ghosts and poltergeists will not attack unless attacked first. Components: quicksilver (mercury in a resin or glue binder, at least 64% mercury). Drawn in two melee rounds; carved and glued in three hours. Power words: Erva yin Xy.', NULL, 'ward', NULL),
  ('Condition: Despair', 0, 1, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.128', 'palladium-fantasy', NULL, 'One minute (4 melee rounds) per level of the Diabolist', 'None', NULL, NULL, NULL, 'Deep sorrow and loneliness: a 1-50% chance the victim surrenders or leaves without a fight (+10% if the foe is the ward''s maker), -2 on initiative, -2 to parry and dodge, -20% on skills. Used with inflict, protection by infliction, area affect and protection from. Protection from despair (printed 133): +4 to save vs magical and psionic despair and sorrow, the banshee''s wail included; a victim who still fails suffers half the penalties and duration. Components: quicksilver (mercury in a resin or glue binder, at least 64% mercury). Drawn in two melee rounds; carved and glued in three hours. Power words: Acba yin Netosa.', NULL, 'ward', NULL),
  ('Condition: Energy', 0, 1, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.128-129', 'palladium-fantasy', NULL, 'One blast per melee round; active one melee round per level of the Diabolist', '1D6 per level of the Diabolist, set by the maker in 1D6 steps', NULL, NULL, NULL, 'An energy blast strikes whoever disturbed the ward - with an area affect symbol, everyone in the radius who fails to save, one blast each per melee round. Used with inflict, protection by infliction, area affect or protection from. Protection from energy (printed 133): all energy attacks, lightning and a dragon''s fire breath included, do half damage, for two minutes per level of the Diabolist. Components: gold (dust in a glue or paste, poured, cast or etched; at least 64% gold). Drawn in two melee rounds; carved and glued in three hours. Power words: Ya-ahk-met.', NULL, 'ward', NULL),
  ('Condition: Evil', 0, 1, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.128', 'palladium-fantasy', NULL, 'Four minutes per level of the Diabolist', 'None', NULL, NULL, NULL, 'A descriptive symbol: makes a phrase exclude, answer to or affect only characters of evil alignment. Used with protection by infliction, area affect or protection from. Protection from evil (printed 133): +1 to save vs magic, psionic or poison attacks from witches, deevils and demons. Components: silver (dust in a glue or paste, poured, cast or etched; at least 64% silver). Drawn in two melee rounds; carved and glued in three hours. Power words: Keron (deevil) or Pein (demon).', NULL, 'ward', NULL),
  ('Condition: Fear', 0, 1, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.129', 'palladium-fantasy', NULL, 'One minute (4 melee rounds) per level of the Diabolist', 'None', NULL, NULL, NULL, 'Terror: a 1-50% chance the victim runs or hides until the magic ends (+10% if the ward''s maker is present), and loses one melee attack each round, -2 on initiative and -20% on skills unless trying to escape. Used with inflict, protection by infliction, area affect and protection from. Protection from fear (printed 133): +4 to save vs fear, magical, psionic or horror factor. Components: quicksilver (mercury in a resin or glue binder, at least 64% mercury). Drawn in two melee rounds; carved and glued in three hours. Power words: Ya-blik.', NULL, 'ward', NULL),
  ('Condition: Fire', 0, 1, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.129', 'palladium-fantasy', NULL, 'One blast per melee round; active one melee round per level of the Diabolist', '1D6 per level of the Diabolist, set by the maker in 1D6 steps', NULL, NULL, NULL, 'A bolt of flame strikes whoever disturbed the ward - with an area affect symbol, everyone in the radius who fails to save, one blast each per melee round. Used with inflict, protection by infliction, area affect or protection from. Protection from fire (printed 133): normal fire does one-third damage and magic fire, elementals included, half. With mystic energy drain it drains magical fires by two torches'' worth per melee round, and a put-out fire cannot be relit until the ward ends. Components: gold (dust in a glue or paste, poured, cast or etched; at least 64% gold). Drawn in two melee rounds; carved and glued in three hours. Power words: Seraph-mytyn.', NULL, 'ward', NULL),
  ('Condition: Good', 0, 1, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.129', 'palladium-fantasy', NULL, 'Four minutes per level of the Diabolist', 'None', NULL, NULL, NULL, 'A descriptive symbol: makes a phrase exclude, answer to or affect only characters of good alignment. Used with protection by infliction, area affect or protection from. The protection list on printed 133 has no entry for good. Components: silver (dust in a glue or paste, poured, cast or etched; at least 64% silver). Drawn in two melee rounds; carved and glued in three hours. Power words: Acba yin Tao-bo yin Acba.', NULL, 'ward', NULL),
  ('Condition: Hate', 0, 1, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.129', 'palladium-fantasy', NULL, 'One minute (4 melee rounds) per level of the Diabolist', 'None', NULL, NULL, NULL, 'Hatred and treachery cloud the victim''s judgement: -2 on all combat rolls and -15% on skills. Short tempered, the victim may lash out with deadly force at whoever startles, angers or annoys, and is then +3 on initiative and +1 to strike and parry. Used with inflict, protection by infliction, area affect and protection from. Protection from hate (printed 133): +2 to save vs mind and mood altering magic or psionics that stir anger, hatred, revenge or berserker rage. Components: quicksilver (mercury in a resin or glue binder, at least 64% mercury). Drawn in two melee rounds; carved and glued in three hours. Power words: Tarm-kin-toe yin Lo-kum.', NULL, 'ward', NULL),
  ('Condition: Invisible', 0, 1, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.129', 'palladium-fantasy', NULL, 'One minute per level of the Diabolist', 'None', NULL, NULL, NULL, 'Turns invisible the person who disturbed the item (or on whom it is inflicted), or the warded object itself. A person so surprised loses initiative for the first melee round. An invisible object is -9 to strike or use and -50% to work on with skills such as picking its lock. Used with inflict, protection by infliction, area affect and protection from. Protection from the invisible (printed 133): the wearer sees the invisible. With mystic energy drain it turns invisible beings visible. Components: silver (dust in a glue or paste, poured, cast or etched; at least 64% silver). Drawn in two melee rounds; carved and glued in three hours. Power words: Cherubot-kyn yin Ya-ahk-met.', NULL, 'ward', NULL),
  ('Condition: Knowledge', 0, 1, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.129', 'palladium-fantasy', NULL, 'One minute (4 melee rounds) per level of the Diabolist', 'None', NULL, NULL, NULL, 'Lends the power to read, speak and understand all languages and to recognize enchantments, all at 80%. Used with inflict (to instil it) and area affect. Protection from knowledge (printed 133): spells, circles and objects that magically instil knowledge, skills or understanding - tongues, eyes of Thoth, eyes of the wolf - do not work. With mystic energy drain all skills are halved for the duration. Components: gold (dust in a glue or paste, poured, cast or etched; at least 64% gold). Drawn in two melee rounds; carved and glued in three hours. Power words: Acba yin Kym-nark-mar.', NULL, 'ward', NULL),
  ('Condition: Light', 0, 1, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.129', 'palladium-fantasy', NULL, 'Five minutes per level of the Diabolist', 'None; undead take 1D6 per melee round from more than two torches of ward light', NULL, NULL, NULL, 'Light equal to one torch per level of the maker. Vampires and other undead take 1D6 per melee round and are blinded by ward light brighter than two torches. Used with inflict, protection by infliction, area affect and protection from. Protection from light (printed 133): those sensitive to, blinded or hurt by light act normally in daylight for one hour per level; not for vampires or undead. With mystic energy drain a lit area dims to a single candle''s light. Components: gold (dust in a glue or paste, poured, cast or etched; at least 64% gold). Drawn in two melee rounds; carved and glued in three hours. Power words: Seraph-mytyn yin Ya-ahk-met.', NULL, 'ward', NULL),
  ('Condition: Magic', 0, 1, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.129', 'palladium-fantasy', 'Magic used on the ward or within 10 feet (3 m) of it', '8 melee rounds per level of the Diabolist', 'Protection from magic', NULL, NULL, NULL, 'A descriptive symbol: the ward answers when magic is used on it or within 10 feet (3 m), or another condition is told to spare, or strike only, practitioners and creatures of magic. Used with protection from, protection by infliction and area affect only. Protection from magic (printed 133): +2 to save vs all magic, wards, circles and curses included. With mystic energy drain (printed 132): drains 2D6 P.P.E. per melee round (each person, with area affect), casting or energizing costs double, and affected magic loses 25% of duration, range and damage. Components: gold (dust in a glue or paste, poured, cast or etched; at least 64% gold). Drawn in two melee rounds; carved and glued in three hours. Power words: Acba yin Xy yin Acba.', NULL, 'ward', NULL),
  ('Condition: Mystic Energy Drain', 0, 1, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.129-132', 'palladium-fantasy', NULL, 'One minute (4 melee rounds) per level of the Diabolist', 'Varies by the paired condition', NULL, NULL, NULL, 'Always paired with a second, purely descriptive condition naming what it drains - cold, confusion, dark, fire, invisibility, knowledge, light or magic (see each). Set off before a spell is cast it negates the spell; under protection by infliction it fires after a spell hits the wearer and halves it. Magic objects and scrolls the maker carries fail inside it, and ranged spells fade on entering. Used with inflict, protection by infliction, area affect and protection from. Protection from it (printed 133): P.P.E. is drained only by blood sacrifice, and this ward and life drain are halved; two minutes per level. Components: gold (dust in a glue or paste, poured, cast or etched; at least 64% gold). Drawn in two melee rounds; carved and glued in three hours. Power words: Xy yin Acba yin Lo-kum.', NULL, 'ward', NULL),
  ('Condition: Sleep', 0, 1, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.132', 'palladium-fantasy', NULL, 'Two melee rounds (30 seconds) per level of the Diabolist', 'None', 'Standard saving throw', NULL, NULL, 'A slumber the victim cannot be roused from unless attacked with deadly force or blood is drawn. Used to inflict, with protection by infliction, area affect and protection from. Protection from sleep (printed 133): impervious to magic or psionic sleep, and awake and alert for the ward''s duration. Components: silver (dust in a glue or paste, poured, cast or etched; at least 64% silver). Drawn in two melee rounds; carved and glued in three hours. Power words: Acba yin Tao-bo.', NULL, 'ward', NULL),
  ('Condition: Undead', 0, 1, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.132', 'palladium-fantasy', NULL, 'Ten minutes per level of the Diabolist', 'None', NULL, NULL, NULL, 'Repels mummies, zombies, vampires and other undead (not animated dead) from the warded person or object, or from an area affect radius, which they can neither enter nor attack into. It cannot make anyone undead. Used with protection from and area affect. Protection from undead (printed 133): impervious to the vampire''s bite and mind control gaze, and wild vampires, mummies and zombies will not attack unless attacked first. Components: quicksilver (mercury in a resin or glue binder, at least 64% mercury). Drawn in two melee rounds; carved and glued in three hours. Power words: Acba yin Netosa yin Agu.', NULL, 'ward', NULL),
  ('Descriptive: Colors', 0, 1, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.132', 'palladium-fantasy', NULL, '10 minutes per level of the Diabolist', 'None', NULL, NULL, NULL, 'Seven colour symbols - black, blue, brown, green, red, white and yellow (plate, printed 127). Usually descriptive, but a colour can be inflicted: the warded object or person, or everything in an area affect radius, turns that colour for the duration. Used to inflict, with protection by infliction and area affect. Components: silver, as the silver condition symbols (at least 64% silver). Two melee rounds to draw or paint, two hours carved. Power words: Acba yin Ariel-Rapere-kyn.', NULL, 'ward', NULL),
  ('Descriptive: Numbers', 0, 1, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.132', 'palladium-fantasy', NULL, 'Permanent indication', 'None', NULL, NULL, NULL, 'Thirteen numeral symbols - 1 to 10, 50, 100 and 1000 (plate, printed 127). Descriptive: they put the wards or phrases of a ward series or sequence in order, so that several on one object go off one at a time as numbered, and can state details of a phrase. Used to inflict, with protection by infliction, protection from and area affect. Components: any substance, drawn or carved. Half a melee round (about 7 seconds) to draw or paint, two hours carved. Power words: Acba yin Lictalon.', NULL, 'ward', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 34 spells rows are in' AS assertion, count(*) AS got, 34 AS want
  FROM spells WHERE name IN ('Alarm: Magic', 'Alarm: Silent', 'Alarm: Sound', 'Alarm: Trigger', 'Major Ward: Area Affect', 'Major Ward: Inflict', 'Major Ward: Permanence', 'Major Ward: Power', 'Major Ward: Protection From', 'Major Ward: Protection by Infliction', 'Condition: Agony', 'Condition: Blind', 'Condition: Burning Pain', 'Condition: Charm', 'Condition: Cold', 'Condition: Confusion', 'Condition: Dark', 'Condition: Death', 'Condition: Despair', 'Condition: Energy', 'Condition: Evil', 'Condition: Fear', 'Condition: Fire', 'Condition: Good', 'Condition: Hate', 'Condition: Invisible', 'Condition: Knowledge', 'Condition: Light', 'Condition: Magic', 'Condition: Mystic Energy Drain', 'Condition: Sleep', 'Condition: Undead', 'Descriptive: Colors', 'Descriptive: Numbers') AND source_book IS NOT NULL;

